import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"调试技巧","description":"","frontmatter":{},"headers":[],"relativePath":"guide/advanced/Debugging.md","filePath":"guide/advanced/Debugging.md"}`),a={name:`guide/advanced/Debugging.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="调试技巧" tabindex="-1">调试技巧 <a class="header-anchor" href="#调试技巧" aria-label="Permalink to “调试技巧”">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to “前言”">​</a></h2><p><a href="./../tutorials/Error.html">错误与异常</a>讲了怎么<strong>读</strong>报错。这一篇更进一步：当程序<strong>不报错、但行为不对</strong>时，怎么把它揪出来。</p><div class="warning custom-block"><p class="custom-block-title">教程依赖</p><p>本教程假设您已完成<a href="./../tutorials/">入门教程</a>，并读过<a href="./../tutorials/Error.html">错误与异常</a>。</p></div><h2 id="第一件事-用调试模式启动" tabindex="-1">第一件事：用调试模式启动 <a class="header-anchor" href="#第一件事-用调试模式启动" aria-label="Permalink to “第一件事：用调试模式启动”">​</a></h2><p>调试模式是排错的利器。以命令行参数 <code>-debug</code> 启动 Emuera：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>Emuera1824.exe -debug</span></span></code></pre></div><p>它提供普通模式没有的能力，详见<a href="./../../translation/Debug_Mode.html">调试模式</a>。</p><h2 id="调试窗口能做什么" tabindex="-1">调试窗口能做什么 <a class="header-anchor" href="#调试窗口能做什么" aria-label="Permalink to “调试窗口能做什么”">​</a></h2><p>调试模式下可以打开<strong>调试窗口</strong>（快捷键 <code>Ctrl+D</code>，或用调试命令 <code>@DEBUG</code>），其中有：</p><ul><li><strong>变量监视</strong>：查看当前所有变量的值。程序“算出个奇怪结果”时，第一时间来看这里；</li><li><strong>堆栈追踪</strong>：看当前调用到了哪个函数、是从哪里调进来的。递归或层层调用出问题时尤其有用；</li><li><strong>调试控制台</strong>：直接输入并执行任意 ERB 代码，边试边看结果。</li></ul><p>在调试控制台里，你可以随时输入变量名查看它的值：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>@ FLAG:0</span></span>
<span class="line"><span>@ NAME:0</span></span></code></pre></div><p><code>@</code> 后面的空格不是必须的。注意，会改变执行流程或需要输入的指令（如 <code>IF</code>、<code>INPUT</code>）在调试命令里不能使用。</p><h2 id="调试命令" tabindex="-1">调试命令 <a class="header-anchor" href="#调试命令" aria-label="Permalink to “调试命令”">​</a></h2><p>在游戏运行中，输入以 <code>@</code> 开头的文本就会被当作调试命令立即执行，比如临时给自己加钱：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>@MONEY = 99999</span></span></code></pre></div><p>完整清单见<a href="./../../translation/Debug_Command.html">调试命令</a>。</p><h2 id="日志与断言" tabindex="-1">日志与断言 <a class="header-anchor" href="#日志与断言" aria-label="Permalink to “日志与断言”">​</a></h2><ul><li><p><strong>日志</strong>：出错或行为异常时，先看根目录的 <code>emuera.log</code>，里面有文件名、行号等细节；</p></li><li><p><strong><code>ASSERT</code></strong>：把“本来不该发生”的前提写下来。一旦不成立，立刻停下并报错，比让错误悄悄传下去好定位得多：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">ASSERT</span><span style="color:#9CDCFE;"> BASE</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> &gt;=</span><span style="color:#B5CEA8;"> 0</span></span></code></pre></div></li><li><p><strong><code>THROW</code></strong>：主动抛出带说明的错误，方便在关键分支确认“到底走到哪了”；</p></li><li><p><strong><code>;#;</code></strong>：只在调试模式下执行的行。可以把临时调试代码留在脚本里，正式运行时自动失效。</p></li></ul><h2 id="只想看某段代码执行没有" tabindex="-1">只想看某段代码执行没有？ <a class="header-anchor" href="#只想看某段代码执行没有" aria-label="Permalink to “只想看某段代码执行没有？”">​</a></h2><p>用调试输出，把信息打到调试控制台，不干扰游戏画面：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">;#;DEBUGPRINTFORML</span><span style="color:#E6E6E6;"> 进入分支 A，MONEY = </span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">MONEY</span><span style="color:#569CD6;">}</span></span></code></pre></div><p><code>DEBUGPRINT</code> 系只在调试模式下输出，且不受 <code>SKIPDISP</code> 影响。</p><h2 id="定位技巧" tabindex="-1">定位技巧 <a class="header-anchor" href="#定位技巧" aria-label="Permalink to “定位技巧”">​</a></h2><h3 id="二分法" tabindex="-1">二分法 <a class="header-anchor" href="#二分法" aria-label="Permalink to “二分法”">​</a></h3><p>当不确定问题出在哪一段时，在中间插一个 <code>THROW 到这里了</code> 或调试输出，看它是否执行到；据此把范围切一半，重复几次就能锁定。</p><h3 id="最小复现" tabindex="-1">最小复现 <a class="header-anchor" href="#最小复现" aria-label="Permalink to “最小复现”">​</a></h3><p>把出问题的功能<strong>单独抽出来</strong>，写成一个最小的脚本去跑。这一步往往在整理的过程中就发现了问题。</p><h3 id="对比-正常-和-异常-的差异" tabindex="-1">对比“正常”和“异常”的差异 <a class="header-anchor" href="#对比-正常-和-异常-的差异" aria-label="Permalink to “对比“正常”和“异常”的差异”">​</a></h3><p>把正常情况和异常情况下<strong>同一批变量的值</strong>并排打印出来，差异点通常就是原因。</p><h2 id="几个常见的-幽灵问题" tabindex="-1">几个常见的“幽灵问题” <a class="header-anchor" href="#几个常见的-幽灵问题" aria-label="Permalink to “几个常见的“幽灵问题””">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th></tr></thead><tbody><tr><td>换台电脑行为不同</td><td>文件读取顺序依赖文件系统，可用 <code>読み込み順をファイル名順にソートする</code> 固定</td></tr><tr><td>升级引擎后报错 / 显示错乱</td><td>兼容性开关未按需设置，见<a href="./../../reference/Compatibility.html">兼容性</a></td></tr><tr><td>同名函数只有第一个生效</td><td>Eramaker/Emuera 的既有规格，可用<code>同名の非イベント関数が複数定義されたとき警告する</code>发现</td></tr><tr><td>存档能存不能读</td><td>游戏代码 / 版本不匹配，用 <code>CHKDATA</code> 查看原因</td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><ul><li>先用 <code>-debug</code> 启动，善用调试窗口的变量监视与堆栈；</li><li>调试命令能当场查看 / 修改运行中的变量；</li><li><code>ASSERT</code> / <code>THROW</code> 让问题尽早暴露；</li><li>二分法 + 最小复现，是定位疑难问题的两把利器；</li><li>遇到“幽灵问题”，先怀疑读取顺序与兼容性开关。</li></ul><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li><a href="./../tutorials/Error.html">错误与异常</a></li><li><a href="./../../reference/Error_Index.html">错误索引表</a></li><li><a href="./../../translation/Debug_Mode.html">调试模式</a></li><li><a href="./../../translation/Debug_Command.html">调试命令</a></li><li><a href="./../../translation/Usage.html">命令行参数</a></li></ul>`,37)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};